#contents.ytd-rich-grid-renderer {
    display: block;
}

ytd-rich-item-renderer #content {
    max-width: 50vw;
}

ytd-rich-item-renderer #content yt-lockup-view-model > div {
    flex-direction: row;
}

ytd-rich-item-renderer #content yt-lockup-view-model > div yt-touch-feedback-shape {
    display: none;
}

ytd-rich-item-renderer #content yt-lockup-view-model > div a {
    width: 350px;
}

ytd-rich-item-renderer #content yt-lockup-view-model > div > div {
    flex-grow: 1;
    max-width: 30vw;
    padding: 10px
}
}
